/**
 * v2 calculated-field expressions. Reuses v1's `calc.*` grammar wholesale (all
 * operators/functions, correct wire emission) and adds {@link field} for v2
 * field references.
 *
 * The v2 twist: v1 emits a referenced field as its **id** when known, else its
 * **name** — and the platform resolves calc field refs by name on compose. v2
 * has no ids at author time, so a field reference emits the field **name**
 * (carried on the `FieldRef` token). That sidesteps the token-resolution problem
 * entirely (the id is buried in the expression *string*, which `resolvePayload`
 * can't reach) — no deploy-time rewrite needed.
 *
 * Lives under `entities/field/` because calculated is a field sub-type
 * (authored through `app` fields, hence re-exported from the `/app`
 * subpath). The terraform path does not support calculated fields yet —
 * `fieldToTf` degrades them with a diagnostic.
 */
import { calc as baseCalc } from "./calc/index.js";
import { makeExpr } from "./calc/runtime.js";
const FIELD_TYPE_TO_EXPR = {
    TEXT: "text",
    RICH_TEXT: "text",
    NUMBER: "number",
    DECIMAL: "decimal",
    BOOLEAN: "bool",
    DATE: "date",
    DATETIME: "datetime",
    PICKLIST: "picklist",
    MULTI_PICKLIST: "multiPicklist",
    USER: "user",
    USER_ID: "user",
    GROUP: "group",
    GROUP_ID: "group",
    ATTACHMENT: "attachment",
    ATTACHMENT_ID: "attachment",
    JSON: "json",
};
export function field(ref) {
    const exprType = FIELD_TYPE_TO_EXPR[ref.fieldType] ?? "text";
    return makeExpr(exprType, () => `"${ref.name.replace(/"/g, '""')}"`, { context: "record" });
}
/** v2 calc namespace — v1's grammar plus `field()` for v2 field references. */
export const calc = { ...baseCalc, field };
export { dateDiffUnit, dateDifUnit, dateTimeTruncPrecision, orderByDirection, predicateOp, weekdayMode, } from "./calc/index.js";
